func (s *Service) startPendingRepresentation(value domain.Information) error {
	if s.representations == nil || len([]byte(value.Content)) > semanticEmbeddingChunkBytes {
		return nil
	}
	return s.representations.Start(value)
}

func (s *Service) ensurePendingRepresentations(ctx context.Context) {
	if s.representations == nil || s.derivedStore == nil || s.semantic == nil {
		return
	}
	for _, asset := range s.authority.ListCurrent() {
		if len([]byte(asset.Content)) > semanticEmbeddingChunkBytes {
			continue
		}
		record, exists := s.derivedStore.GetWithEmbedding(asset.ID)
		if !exists || record.AssetRevision != asset.Revision || len(record.Embedding) > 0 {
			continue
		}
		vector, err := s.representations.Ensure(ctx, asset)
		if err != nil || len(vector) == 0 {
			continue
		}
		unlock := s.lockMutation(asset.ID)
		current, currentExists := s.authority.ReadCurrent(asset.ID)
		latest, recordExists := s.derivedStore.GetWithEmbedding(asset.ID)
		if !currentExists || !recordExists || current.Revision != asset.Revision || latest.AssetRevision != asset.Revision {
			s.representations.Invalidate(asset.ID, asset.Revision+1)
			unlock()
			continue
		}
		latest.Embedding = append([]float32(nil), vector...)
		latest.EmbeddingSpace = s.embedder.Space().ID
		if latest.SemanticReceipt != nil {
			latest.Status = "ready"
			latest.Error = ""
			if latest.SemanticReceipt.Status == semantics.SubmissionUncertain {
				latest.Status = "uncertain"
				latest.Error = latest.SemanticReceipt.Uncertainty
			}
		}
		s.graphMu.Lock()
		putErr := s.derivedStore.Put(latest)
		if putErr == nil {
			s.semantic.Upsert(latest)
			_ = s.representations.Commit(latest.AssetID, latest.AssetRevision)
		}
		s.graphMu.Unlock()
		unlock()
	}
}

